import { sql } from "drizzle-orm";
import { pgTable, text, varchar, integer, timestamp } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const businesses = pgTable("businesses", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  name: text("name").notNull(),
  category: text("category").notNull().default(""),
  logo: text("logo").default(""),
  googleReviewUrl: text("google_review_url").notNull().default(""),
  publicSlug: text("public_slug").notNull().unique(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const feedback = pgTable("feedback", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  businessId: varchar("business_id").notNull().references(() => businesses.id),
  rating: integer("rating").notNull(),
  feedbackText: text("feedback_text").default(""),
  generatedReview: text("generated_review").default(""),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const insertUserSchema = createInsertSchema(users).omit({ id: true, createdAt: true });
export const insertBusinessSchema = createInsertSchema(businesses).omit({ id: true, createdAt: true });
export const insertFeedbackSchema = createInsertSchema(feedback).omit({ id: true, createdAt: true });

export const signupSchema = z.object({
  email: z.string().email("Please enter a valid email"),
  password: z.string().min(8, "Password must be at least 8 characters"),
});

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;
export type InsertBusiness = z.infer<typeof insertBusinessSchema>;
export type Business = typeof businesses.$inferSelect;
export type InsertFeedback = z.infer<typeof insertFeedbackSchema>;
export type Feedback = typeof feedback.$inferSelect;

import { drizzle } from "drizzle-orm/node-postgres";
import pg from "pg";
import * as schema from "@shared/schema";

const { Pool } = pg;

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

export const db = drizzle(pool, { schema });

import { eq, desc } from "drizzle-orm";
import { db } from "./db";
import {
  users, businesses, feedback,
  type User, type InsertUser,
  type Business, type InsertBusiness,
  type Feedback, type InsertFeedback,
} from "@shared/schema";
import { sql } from "drizzle-orm";

export interface IStorage {
  // Users
  getUserById(id: string): Promise<User | undefined>;
  getUserByEmail(email: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;

  // Businesses
  getBusinessByUserId(userId: string): Promise<Business | undefined>;
  getBusinessBySlug(slug: string): Promise<Business | undefined>;
  createBusiness(business: InsertBusiness): Promise<Business>;
  updateBusiness(id: string, updates: Partial<InsertBusiness>): Promise<Business>;

  // Feedback
  getFeedbackByBusinessId(businessId: string): Promise<Feedback[]>;
  createFeedback(item: InsertFeedback): Promise<Feedback>;
  getDashboardStats(businessId: string): Promise<{
    totalRatings: number;
    avgRating: number;
    aiReviewsGenerated: number;
    privateFeedback: number;
  }>;
}

export class DatabaseStorage implements IStorage {
  async getUserById(id: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.id, id));
    return user;
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.email, email));
    return user;
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const [user] = await db.insert(users).values(insertUser).returning();
    return user;
  }

  async getBusinessByUserId(userId: string): Promise<Business | undefined> {
    const [business] = await db.select().from(businesses).where(eq(businesses.userId, userId));
    return business;
  }

  async getBusinessBySlug(slug: string): Promise<Business | undefined> {
    const [business] = await db.select().from(businesses).where(eq(businesses.publicSlug, slug));
    return business;
  }

  async createBusiness(insertBusiness: InsertBusiness): Promise<Business> {
    const [business] = await db.insert(businesses).values(insertBusiness).returning();
    return business;
  }

  async updateBusiness(id: string, updates: Partial<InsertBusiness>): Promise<Business> {
    const [business] = await db
      .update(businesses)
      .set(updates)
      .where(eq(businesses.id, id))
      .returning();
    return business;
  }

  async getFeedbackByBusinessId(businessId: string): Promise<Feedback[]> {
    return db
      .select()
      .from(feedback)
      .where(eq(feedback.businessId, businessId))
      .orderBy(desc(feedback.createdAt));
  }

  async createFeedback(item: InsertFeedback): Promise<Feedback> {
    const [created] = await db.insert(feedback).values(item).returning();
    return created;
  }

  async getDashboardStats(businessId: string): Promise<{
    totalRatings: number;
    avgRating: number;
    aiReviewsGenerated: number;
    privateFeedback: number;
  }> {
    const items = await db.select().from(feedback).where(eq(feedback.businessId, businessId));
    const totalRatings = items.length;
    const avgRating = totalRatings > 0
      ? Math.round((items.reduce((s, f) => s + f.rating, 0) / totalRatings) * 10) / 10
      : 0;
    const aiReviewsGenerated = items.filter(f => f.generatedReview && f.generatedReview.length > 0).length;
    const privateFeedback = items.filter(f => f.rating <= 3).length;
    return { totalRatings, avgRating, aiReviewsGenerated, privateFeedback };
  }
}

export const storage = new DatabaseStorage();

import { createContext, useContext, useState, useEffect } from "react";
import { apiRequest } from "@/lib/queryClient";

interface AuthUser {
  id: string;
  email: string;
}

interface AuthContextType {
  user: AuthUser | null;
  isLoading: boolean;
  login: (email: string, password: string) => Promise<void>;
  signup: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetch("/api/auth/me", { credentials: "include" })
      .then(r => r.ok ? r.json() : null)
      .then(data => setUser(data?.user ?? null))
      .catch(() => setUser(null))
      .finally(() => setIsLoading(false));
  }, []);

  const login = async (email: string, password: string) => {
    const res = await apiRequest("POST", "/api/auth/login", { email, password });
    const data = await res.json();
    setUser(data.user);
  };

  const signup = async (email: string, password: string) => {
    const res = await apiRequest("POST", "/api/auth/signup", { email, password });
    const data = await res.json();
    setUser(data.user);
  };

  const logout = async () => {
    await apiRequest("POST", "/api/auth/logout");
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, isLoading, login, signup, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}

import type { Express, Request, Response } from "express";
import { createServer, type Server } from "http";
import session from "express-session";
import connectPgSimple from "connect-pg-simple";
import bcrypt from "bcryptjs";
import OpenAI from "openai";
import QRCode from "qrcode";
import pg from "pg";
import { storage } from "./storage";
import { signupSchema, loginSchema } from "@shared/schema";

const PgSession = connectPgSimple(session);
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

declare module "express-session" {
  interface SessionData {
    userId: string;
  }
}

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

function slugify(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function requireAuth(req: Request, res: Response, next: Function) {
  if (!req.session?.userId) {
    return res.status(401).json({ message: "Unauthorized" });
  }
  next();
}

export async function registerRoutes(httpServer: Server, app: Express): Promise<Server> {
  app.use(
    session({
      store: new PgSession({ pool, createTableIfMissing: true }),
      secret: process.env.SESSION_SECRET || "reviewai-secret-key-change-in-prod",
      resave: false,
      saveUninitialized: false,
      cookie: { secure: false, httpOnly: true, maxAge: 7 * 24 * 60 * 60 * 1000 },
    })
  );

  // ── AUTH ─────────────────────────────────────────────────────────────────────

  app.post("/api/auth/signup", async (req, res) => {
    const result = signupSchema.safeParse(req.body);
    if (!result.success) return res.status(400).json({ message: result.error.issues[0].message });
    const { email, password } = result.data;

    const existing = await storage.getUserByEmail(email);
    if (existing) return res.status(409).json({ message: "An account with this email already exists" });

    const passwordHash = await bcrypt.hash(password, 12);
    const user = await storage.createUser({ email, passwordHash });

    // Create a default business for the user
    const slug = `${slugify(email.split("@")[0])}-${Date.now().toString(36)}`;
    await storage.createBusiness({
      userId: user.id,
      name: "",
      category: "",
      logo: "",
      googleReviewUrl: "",
      publicSlug: slug,
    });

    req.session.userId = user.id;
    res.json({ user: { id: user.id, email: user.email } });
  });

  app.post("/api/auth/login", async (req, res) => {
    const result = loginSchema.safeParse(req.body);
    if (!result.success) return res.status(400).json({ message: "Invalid credentials" });
    const { email, password } = result.data;

    const user = await storage.getUserByEmail(email);
    if (!user) return res.status(401).json({ message: "Invalid email or password" });

    const valid = await bcrypt.compare(password, user.passwordHash);
    if (!valid) return res.status(401).json({ message: "Invalid email or password" });

    req.session.userId = user.id;
    res.json({ user: { id: user.id, email: user.email } });
  });

  app.post("/api/auth/logout", (req, res) => {
    req.session.destroy(() => {});
    res.json({ ok: true });
  });

  app.get("/api/auth/me", async (req, res) => {
    if (!req.session?.userId) return res.status(401).json({ message: "Not authenticated" });
    const user = await storage.getUserById(req.session.userId);
    if (!user) return res.status(401).json({ message: "Not authenticated" });
    res.json({ user: { id: user.id, email: user.email } });
  });

  // ── BUSINESS ─────────────────────────────────────────────────────────────────

  app.get("/api/business", requireAuth, async (req, res) => {
    const business = await storage.getBusinessByUserId(req.session.userId!);
    if (!business) return res.status(404).json({ message: "No business found" });
    res.json(business);
  });

  app.put("/api/business", requireAuth, async (req, res) => {
    const business = await storage.getBusinessByUserId(req.session.userId!);
    if (!business) return res.status(404).json({ message: "No business found" });

    const { name, category, logo, googleReviewUrl } = req.body;
    const updated = await storage.updateBusiness(business.id, {
      name: name ?? business.name,
      category: category ?? business.category,
      logo: logo ?? business.logo,
      googleReviewUrl: googleReviewUrl ?? business.googleReviewUrl,
    });
    res.json(updated);
  });

  // Public: get business by slug
  app.get("/api/r/:slug", async (req, res) => {
    const business = await storage.getBusinessBySlug(req.params.slug);
    if (!business) return res.status(404).json({ message: "Business not found" });
    // Only expose safe fields
    res.json({
      id: business.id,
      name: business.name,
      category: business.category,
      logo: business.logo,
      googleReviewUrl: business.googleReviewUrl,
    });
  });

  // QR code for business
  app.get("/api/business/qr", requireAuth, async (req, res) => {
    const business = await storage.getBusinessByUserId(req.session.userId!);
    if (!business) return res.status(404).json({ message: "No business found" });
    const url = `${req.protocol}://${req.get("host")}/r/${business.publicSlug}`;
    const qrDataUrl = await QRCode.toDataURL(url, {
      errorCorrectionLevel: "M",
      margin: 2,
      color: { dark: "#6D28D9", light: "#FFFFFF" },
    });
    res.json({ qr: qrDataUrl, url });
  });

  // ── FEEDBACK ──────────────────────────────────────────────────────────────────

  app.get("/api/feedback", requireAuth, async (req, res) => {
    const business = await storage.getBusinessByUserId(req.session.userId!);
    if (!business) return res.status(404).json({ message: "No business found" });
    const items = await storage.getFeedbackByBusinessId(business.id);
    res.json(items);
  });

  app.post("/api/feedback", async (req, res) => {
    const { businessId, rating, feedbackText, generatedReview } = req.body;
    if (!businessId || !rating) return res.status(400).json({ message: "businessId and rating are required" });
    if (rating < 1 || rating > 5) return res.status(400).json({ message: "Rating must be 1-5" });
    const item = await storage.createFeedback({ businessId, rating, feedbackText: feedbackText || "", generatedReview: generatedReview || "" });
    res.json(item);
  });

  // ── DASHBOARD STATS ───────────────────────────────────────────────────────────

  app.get("/api/dashboard/stats", requireAuth, async (req, res) => {
    const business = await storage.getBusinessByUserId(req.session.userId!);
    if (!business) return res.status(404).json({ message: "No business found" });
    const stats = await storage.getDashboardStats(business.id);
    res.json(stats);
  });

  // ── AI REVIEW GENERATION ──────────────────────────────────────────────────────

  app.post("/api/generate-review", async (req, res) => {
    const { businessName, category, rating, experience, employeeName } = req.body;
    if (!businessName || !rating) return res.status(400).json({ message: "businessName and rating are required" });

    if (!process.env.OPENAI_API_KEY) {
      // Return placeholder if no API key configured
      return res.json({
        review: `Had a wonderful experience at ${businessName}. The staff were attentive and the quality was excellent. Will definitely be coming back soon!`,
      });
    }

    const stars = "★".repeat(rating) + "☆".repeat(5 - rating);
    const prompt = `Business Name: ${businessName}
Business Type: ${category || "local business"}
Star Rating: ${rating}/5 ${stars}
Customer Experience: ${experience || "No additional comments provided."}
Staff Name: ${employeeName || "Not provided."}

Write ONE authentic Google review that sounds like it was written naturally by a real customer.

Rules:
- The review MUST naturally mention the business name "${businessName}" at least once.
- Base the review primarily on the star rating.
- If the customer wrote additional comments, use them naturally in the review.
- If the customer didn't write anything, create a believable review based only on the star rating and business type.
- If a staff name is provided, mention it naturally. If not provided, never invent a person's name.
- Never fabricate specific experiences that the customer did not provide.
- Keep the tone human, conversational, and trustworthy.
- Every generation should have different wording and sentence structure.
- Never sound robotic or AI-generated.
- Avoid clichés like "I highly recommend this place" in every response.
- Do not overuse words like amazing, outstanding, excellent, perfect, or fantastic.
- Keep the review between 40 and 100 words.
- Use proper grammar and punctuation.
- Return ONLY the review text without quotation marks, titles, or explanations.`;

    const completion = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: "You are an expert review writing assistant. Write natural Google reviews that sound like genuine customers. Never mention AI. Never sound robotic." },
        { role: "user", content: prompt },
      ],
      max_tokens: 200,
      temperature: 0.9,
    });

    const review = completion.choices[0].message.content?.trim() || "";
    res.json({ review });
  });

  return httpServer;
}

