  );
}

import { useState } from "react";
import { Link, useLocation } from "wouter";
import { useAuth } from "@/hooks/use-auth";
import { useToast } from "@/hooks/use-toast";

export default function Signup() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const { signup } = useAuth();
  const { toast } = useToast();
  const [, navigate] = useLocation();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password.length < 8) {
      toast({ title: "Password too short", description: "Password must be at least 8 characters.", variant: "destructive" });
      return;
    }
    setLoading(true);
    try {
      await signup(email, password);
      navigate("/business");
    } catch (err: any) {
      toast({ title: "Signup failed", description: err.message, variant: "destructive" });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#FAFAFC] flex flex-col items-center justify-center px-4 font-['Poppins',sans-serif]">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <Link href="/">
            <a className="text-[#6D28D9] text-2xl font-bold">ReviewAI</a>
          </Link>
          <p className="text-[#6B7280] text-sm mt-1">by Adshree</p>
        </div>

        <div className="bg-white rounded-2xl border border-[#ECECF2] shadow-sm p-8">
          <h1 className="text-[#111827] text-xl font-semibold mb-1">Create your account</h1>
          <p className="text-[#6B7280] text-sm mb-6">Start collecting Google reviews in minutes</p>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-[#111827] mb-1.5">Email</label>
              <input
                type="email"
                required
                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder="you@example.com"
                className="w-full px-4 py-2.5 rounded-xl border border-[#ECECF2] bg-[#FAFAFC] text-[#111827] text-sm placeholder:text-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#6D28D9]/20 focus:border-[#6D28D9] transition-colors"
                data-testid="input-email"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-[#111827] mb-1.5">Password</label>
              <input
                type="password"
                required
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="Min. 8 characters"
                className="w-full px-4 py-2.5 rounded-xl border border-[#ECECF2] bg-[#FAFAFC] text-[#111827] text-sm placeholder:text-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#6D28D9]/20 focus:border-[#6D28D9] transition-colors"
                data-testid="input-password"
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="w-full py-2.5 px-4 bg-[#6D28D9] hover:bg-[#5B21B6] text-white text-sm font-medium rounded-xl transition-colors disabled:opacity-60"
              data-testid="button-signup"
            >
              {loading ? "Creating account…" : "Create account"}
            </button>
          </form>

          <p className="text-center text-sm text-[#6B7280] mt-6">
            Already have an account?{" "}
            <Link href="/login">
              <a className="text-[#6D28D9] font-medium hover:underline">Sign in</a>
            </Link>
          </p>
        </div>

        <p className="text-center text-xs text-[#9CA3AF] mt-8">Powered by Adshree Inc.</p>
      </div>
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Users, Star, Sparkles, MessageSquare, TrendingUp, TrendingDown } from "lucide-react";
import MerchantLayout from "@/components/MerchantLayout";
import { useAuth } from "@/hooks/use-auth";
import type { Feedback, Business } from "@shared/schema";

function StatCard({
  label, value, icon: Icon, iconBg, badge, badgeUp,
}: {
  label: string; value: string | number; icon: any; iconBg: string;
  badge?: string; badgeUp?: boolean;
}) {
  return (
    <div className="bg-white rounded-2xl border border-[#ECECF2] p-6 shadow-sm">
      <div className="flex items-start justify-between mb-4">
        <div className={`${iconBg} p-2.5 rounded-xl`}>
          <Icon size={18} strokeWidth={1.8} className="text-inherit" />
        </div>
        {badge && (
          <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${badgeUp ? "bg-green-50 text-[#16A34A]" : "bg-red-50 text-red-600"}`}>
            {badge}
          </span>
        )}
      </div>
      <div className="text-2xl font-bold text-[#111827] leading-tight">{value}</div>
      <div className="text-xs text-[#6B7280] mt-1 font-medium tracking-wide uppercase">{label}</div>
    </div>
  );
}

function RatingBar({ stars, count, total }: { stars: number; count: number; total: number }) {
  const pct = total > 0 ? Math.round((count / total) * 100) : 0;
  return (
    <div className="flex items-center gap-3">
      <span className="text-xs text-[#6B7280] w-8 text-right font-medium">{stars}★</span>
      <div className="flex-1 bg-[#F3F4F6] h-2 rounded-full overflow-hidden">
        <div
          className="h-full rounded-full bg-[#6D28D9]"
          style={{ width: `${pct}%`, opacity: 0.3 + (stars / 5) * 0.7 }}
        />
      </div>
      <span className="text-xs text-[#6B7280] w-8 font-medium">{pct}%</span>
    </div>
  );
}

export default function Dashboard() {
  const { user } = useAuth();

  const { data: stats } = useQuery<{ totalRatings: number; avgRating: number; aiReviewsGenerated: number; privateFeedback: number }>({
    queryKey: ["/api/dashboard/stats"],
